SELECT `event.id` FROM `events` WHERE `event.category` = 'process' AND `host.os.type` = 'windows' AND ((((`process.executable` ilike '%\\\\a.exe' OR `process.executable` ilike '%\\\\b.exe') AND (`process.executable` ilike '%\\\\a.exe' AND `process.executable` ilike '%\\\\b.exe')) AND (`user.name` ilike 'root' OR `process.executable` ilike '%\\\\a.exe' OR `process.executable` ilike '%\\\\b.exe')) AND NOT (`user.name` ilike 'root' AND `process.executable` ilike '%\\\\a.exe' AND `process.executable` ilike '%\\\\b.exe'))
